package com.techie345.moneys.financial.snapshot;
import java.time.*; import java.util.UUID; import com.techie345.moneys.financial.FinancialEntity; import jakarta.persistence.*;
 @Entity @Table(name="net_worth_snapshot") public class SnapshotEntity extends FinancialEntity { @Column(name="snapshot_date",nullable=false) LocalDate date; @Column(name="assets_cents",nullable=false) long assetsCents; @Column(name="liabilities_cents",nullable=false) long liabilitiesCents; @Column(name="net_worth_cents",nullable=false) long netWorthCents; UUID accountId; String source; String sourceFile; Instant importedAt; protected SnapshotEntity(){} public SnapshotEntity(UUID o,LocalDate d,long a,long l,long n,UUID ac,String s,String f,Instant i){validate(o,d,a,l,n);ownerId=o;date=d;assetsCents=a;liabilitiesCents=l;netWorthCents=n;accountId=ac;source=s;sourceFile=f;importedAt=i;} private static void validate(UUID o,LocalDate d,long a,long l,long n){if(o==null||d==null||a<0||l<0||n!=a-l)throw new IllegalArgumentException("invalid net worth snapshot");} public LocalDate getDate(){return date;} public long getAssetsCents(){return assetsCents;} public long getLiabilitiesCents(){return liabilitiesCents;} public long getNetWorthCents(){return netWorthCents;} public UUID getAccountId(){return accountId;} public String getSource(){return source;} public String getSourceFile(){return sourceFile;} public Instant getImportedAt(){return importedAt;} public void update(LocalDate d,long a,long l,long n,UUID ac,String s,String f,Instant i){validate(ownerId,d,a,l,n);date=d;assetsCents=a;liabilitiesCents=l;netWorthCents=n;accountId=ac;source=s;sourceFile=f;importedAt=i;} }
